const $=selector=>document.querySelector(selector),out=$('#out'),solField=$('#sol'),analyze=$('#analyze'),download=$('#download');
let report=null;
const identity=record=>String(record?.imageid||record?.image_id||record?.filename||'').replace(/_+$/,'');
const vector=value=>String(value||'').match(/-?\d*\.?\d+(?:e[+-]?\d+)?/ig)?.map(Number)||null;
const positionKey=record=>{const position=vector(record.xyz||record.rover_position||record.roverPosition);return position?.length===3?`xyz:${position.map(value=>value.toFixed(2)).join(',')}`:`rmc:${record.site??'—'}/${record.drive??'—'}`};
const isGeometryReady=record=>Boolean(record.camera_model_component_list||record.camera?.camera_model_component_list||record.camera_vector||record.camera?.camera_vector);
function summarize(records){const groups=new Map;for(const record of records){const key=positionKey(record);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(record)}const locations=[...groups].map(([key,items])=>({key,records:items.length,geometryReady:items.filter(isGeometryReady).length,sols:[...new Set(items.map(item=>item.sol))].sort((a,b)=>a-b),timeRange:[items[0]?.date_taken||items[0]?.date_received||null,items.at(-1)?.date_taken||items.at(-1)?.date_received||null],siteDrive:[...new Set(items.map(item=>`${item.site??'—'}/${item.drive??'—'}`))],instruments:[...new Set(items.map(item=>item.instrument||item.camera?.instrument||'—'))],imageIds:items.map(identity)})).sort((a,b)=>a.timeRange[0]?.localeCompare(b.timeRange[0]||'')||0);const maximum=Math.max(0,...locations.map(location=>location.geometryReady)),minimum=Math.max(4,Math.min(8,Math.ceil(maximum*.1)));return{positionGroups:locations,proposedPanoramaStations:locations.filter(location=>location.geometryReady>=minimum),minimumGeometryReadyViews:minimum}}
async function fetchSol(sol){let records=[],page=0,more=true;while(more){const params=new URLSearchParams({order:'sol asc,date_taken asc',per_page:'100',page:String(page),condition_1:'msl:mission',condition_2:`${sol}:sol:gte`,condition_3:`${sol}:sol:lte`,search:'',extended:''}),response=await fetch(`https://mars.nasa.gov/api/v1/raw_image_items?${params}`),data=await response.json();if(!response.ok)throw Error(`NASA request failed for Sol ${sol}`);records.push(...(data.items||[]));more=Boolean(data.more);page++}return records.sort((a,b)=>String(a.date_taken||a.date_received||'').localeCompare(String(b.date_taken||b.date_received||'')))}
async function run(){const sol=Number(solField.value);if(!Number.isInteger(sol)||sol<0){out.textContent='Enter a non-negative integer Sol.';return}history.replaceState(null,'',`?sol=${sol}`);analyze.disabled=true;download.disabled=true;out.textContent=`Loading all NASA records for Sol ${sol}…`;try{const records=await fetchSol(sol),summary=summarize(records);report={format:'mars-rover-360-location-diagnostic/v1',createdAt:new Date().toISOString(),requestedSol:sol,summary:{rawRecords:records.length,geometryReadyRecords:records.filter(isGeometryReady).length,...summary},records};out.textContent=JSON.stringify(report,null,2);download.disabled=false}catch(error){report=null;out.textContent=`ERROR: ${error.message}`}finally{analyze.disabled=false}}
analyze.onclick=run;download.onclick=()=>{if(!report)return;const href=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=href;link.download=`location-diagnostic-sol-${report.requestedSol}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(href),1000)};
const requested=Number(new URLSearchParams(location.search).get('sol'));if(Number.isInteger(requested)&&requested>=0){solField.value=requested;run()}
